/// Looks up a language table.
#[must_use]
pub fn lookup(lang: &str) -> Option<&'static [&'static str]> {
    match lang {
        "ar" => Some(AR),
        "bg" => Some(BG),
        "ca" => Some(CA),
        "ckb" => Some(CKB),
        "cs" => Some(CS),
        "da" => Some(DA),
        "de" => Some(DE),
        "el" => Some(EL),
        _ => None,
    }
}
